(6188252, 913680, 121916, '<td valign="top">This is beautiful in every way.  It is mystical, yet full of realism.  An engaging combination.</td>', 'This is beautiful in every way.  It is mystical, yet full of realism.  An engaging combination.', '2010-10-11 08:36:20.000000', NULL, 1),
(6188262, 913854, 54446, '<td valign="top">A pretty good title.  The image has some interesting elements.</td>', 'A pretty good title.  The image has some interesting elements.', '2010-10-11 08:45:20.000000', NULL, 1),
(6188263, 913665, 54446, '<td valign="top">Maybe a little abstract, but not very interesting.</td>', 'Maybe a little abstract, but not very interesting.', '2010-10-11 08:45:31.000000', NULL, 1),
