(6189836, 913700, 119419, '<td valign="top">love it, so alive</td>', 'love it, so alive', '2010-10-12 23:39:18.000000', NULL, 1),
(6189841, 913750, 119419, '<td valign="top">ouch!</td>', 'ouch!', '2010-10-12 23:42:17.000000', NULL, 1),
(6189842, 913890, 119419, '<td valign="top">very gentle and soft</td>', 'very gentle and soft', '2010-10-12 23:43:05.000000', NULL, 1),
(6189886, 913573, 27662, '<td valign="top">Absolutely gorgeous!!  Love the leap and the lighting!</td>', 'Absolutely gorgeous!!  Love the leap and the lighting!', '2010-10-13 00:07:20.000000', NULL, 1),
(6189891, 913802, 119419, '<td valign="top">brilliant</td>', 'brilliant', '2010-10-13 00:09:02.000000', NULL, 1),
