(6191110, 913133, 122115, '<td valign="top">Nice picture</td>', 'Nice picture', '2010-10-13 20:32:06.000000', NULL, 1),
(6191347, 913522, 30861, '<td valign="top">This is extremely well done. Well enough done that I can''t really tell if you DID use flash, except that my experience with similar scenes suggest you almost had to have. So, perfectly balanced :-) <br/> <br/>Looks like a Richard Hahn (which is a compliment, if you don''t happen to be him).</td>', 'This is extremely well done. Well enough done that I can''t really tell if you DID use flash, except that my experience with similar scenes suggest you almost had to have. So, perfectly balanced :-)  Looks like a Richard Hahn (which is a compliment, if you don''t happen to be him).', '2010-10-14 01:20:24.000000', NULL, 1),
