(6191708, 913854, 62989, '<td valign="top">I really like titles that send me scurryinbg off to google - so I''m grateful for the introduction to the poem - i sort of wish the whoile picture had the same feel as the bottom right quadrant - ut it is interesting and full of movement</td>', 'I really like titles that send me scurryinbg off to google - so I''m grateful for the introduction to the poem - i sort of wish the whoile picture had the same feel as the bottom right quadrant - ut it is interesting and full of movement', '2010-10-14 14:01:45.000000', NULL, 1),
(6191880, 913909, 86322, '<td valign="top">Love the expression in his eyes. 9</td>', 'Love the expression in his eyes. 9', '2010-10-14 19:15:52.000000', NULL, 1),
(6191881, 913751, 86322, '<td valign="top">Great photo, wouldve loved to see more space over his head or less under his feet, but that''s just my taste. 9</td>', 'Great photo, wouldve loved to see more space over his head or less under his feet, but that''s just my taste. 9', '2010-10-14 19:17:33.000000', NULL, 1),
